def semver_sort(versions):
    def parse_version(v):
        # Split build metadata (ignore it)
        if '+' in v:
            v = v.split('+')[0]

        # Split pre-release
        if '-' in v:
            base, prerelease = v.split('-', 1)
        else:
            base = v
            prerelease = None

        # Parse MAJOR.MINOR.PATCH
        parts = base.split('.')
        major = int(parts[0])
        minor = int(parts[1]) if len(parts) > 1 else 0
        patch = int(parts[2]) if len(parts) > 2 else 0

        # Parse pre-release identifiers
        if prerelease is not None:
            identifiers = prerelease.split('.')
            parsed_identifiers = []
            for identifier in identifiers:
                if identifier.isdigit():
                    parsed_identifiers.append((0, int(identifier)))
                else:
                    parsed_identifiers.append((1, identifier))
        else:
            parsed_identifiers = None

        return (major, minor, patch, parsed_identifiers)

    def compare_key(v):
        major, minor, patch, prerelease = parse_version(v)

        # For sorting: versions with prerelease come before those without
        # If prerelease is None, we use a tuple that sorts after any prerelease
        if prerelease is None:
            prerelease_key = (1,)  # Sorts after (0, ...)
        else:
            prerelease_key = (0, prerelease)

        return (major, minor, patch, prerelease_key)

    # Stable sort preserves input order for equal elements
    return sorted(versions, key=compare_key)

